```turtle
@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing securities, derivatives, cash instruments, market participants, and related financial concepts as described in domain reference texts."@en .

#################################################################
#    Annotation Properties
#################################################################

rdfs:label a owl:AnnotationProperty .
rdfs:comment a owl:AnnotationProperty .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has issuer"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Issuer ;
    owl:inverseOf fis:isIssuerOf .

fis:isIssuerOf a owl:ObjectProperty ;
    rdfs:label "is issuer of"@en ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasIssuer .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:label "has underlying"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlying ;
    owl:inverseOf fis:isUnderlyingOf .

fis:isUnderlyingOf a owl:ObjectProperty ;
    rdfs:label "is underlying of"@en ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:Derivative ;
    owl:inverseOf fis:hasUnderlying .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:label "has collateral"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Collateral ;
    owl:inverseOf fis:isCollateralOf .

fis:isCollateralOf a owl:ObjectProperty ;
    rdfs:label "is collateral of"@en ;
    rdfs:domain fis:Collateral ;
    rdfs:range fis:DebtSecurity ;
    owl:inverseOf fis:hasCollateral .

fis:hasExchange a owl:ObjectProperty ;
    rdfs:label "has exchange"@en ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Exchange ;
    owl:inverseOf fis:isExchangeOf .

fis:isExchangeOf a owl:ObjectProperty ;
    rdfs:label "is exchange of"@en ;
    rdfs:domain fis:Exchange ;
    rdfs:range fis:Security ;
    owl:inverseOf fis:hasExchange .

fis:hasInvestor a owl:ObjectProperty ;
    rdfs:label "has investor"@en ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Investor ;
    owl:inverseOf fis:isInvestorOf .

fis:isInvestorOf a owl:ObjectProperty ;
    rdfs:label "is investor of"@en ;
    rdfs:domain fis:Investor ;
    rdfs:range fis:Security ;
    owl:inverseOf fis:hasInvestor .

fis:hasShareholder a owl:ObjectProperty ;
    rdfs:label "has shareholder"@en ;
    rdfs:subPropertyOf fis:hasInvestor ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Shareholder ;
    owl:inverseOf fis:isShareholderOf .

fis:isShareholderOf a owl:ObjectProperty ;
    rdfs:label "is shareholder of"@en ;
    rdfs:subPropertyOf fis:isInvestorOf ;
    rdfs:domain fis:Shareholder ;
    rdfs:range fis:EquitySecurity ;
    owl:inverseOf fis:hasShareholder .

fis:hasBondholder a owl:ObjectProperty ;
    rdfs:label "has bondholder"@en ;
    rdfs:subPropertyOf fis:hasInvestor ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Bondholder ;
    owl:inverseOf fis:isBondholderOf .

fis:isBondholderOf a owl:ObjectProperty ;
    rdfs:label "is bondholder of"@en ;
    rdfs:subPropertyOf fis:isInvestorOf ;
    rdfs:domain fis:Bondholder ;
    rdfs:range fis:Bond ;
    owl:inverseOf fis:hasBondholder .

fis:hasPortfolio a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has portfolio"@en ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Portfolio ;
    owl:inverseOf fis:isPortfolioOf .

fis:isPortfolioOf a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is portfolio of"@en ;
    rdfs:domain fis:Portfolio ;
    rdfs:range fis:InvestmentFund ;
    owl:inverseOf fis:hasPortfolio .

fis:hasCommonStock a owl:ObjectProperty ;
    rdfs:label "has common stock"@en ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range fis:CommonStock ;
    owl:inverseOf fis:isCommonStockOf .

fis:isCommonStockOf a owl:ObjectProperty ;
    rdfs:label "is common stock of"@en ;
    rdfs:domain fis:CommonStock ;
    rdfs:range fis:ConvertibleBond ;
    owl:inverseOf fis:hasCommonStock .

#################################################################
#    Data Properties
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has maturity date"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:string .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has strike price"@en ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasParValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has par value"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has coupon rate"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasIsin a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has ISIN"@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string .

fis:hasConversionPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has conversion price"@en ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:decimal .

fis:hasConversionRatio a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has conversion ratio"@en ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has notional amount"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:decimal .

#################################################################
#    Classes: Top-Level Hierarchy
#################################################################

fis:Underlying a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Underlying"@en, "Underlier"@en ;
    rdfs:comment "The reference asset, rate, index, currency, commodity, or event on which a derivative is based."@en .

fis:Commodity a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Commodity"@en .

fis:PriceIndex a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Price Index"@en .

fis:Currency a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Currency"@en .

fis:InterestRate a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Interest Rate"@en .

fis:Portfolio a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Portfolio"@en ;
    rdfs:comment "A combined pool of investment assets or securities held by an investment entity."@en .

fis:Collateral a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Collateral"@en ;
    rdfs:comment "An asset or pool of assets pledged or transferred to secure the performance of an obligation."@en .

fis:AssetPool a owl:Class ;
    rdfs:subClassOf fis:Collateral ;
    rdfs:label "Asset Pool"@en .

fis:MortgagePool a owl:Class ;
    rdfs:subClassOf fis:AssetPool ;
    rdfs:label "Mortgage Pool"@en .

fis:ResidentialMortgagePool a owl:Class ;
    rdfs:subClassOf fis:MortgagePool ;
    rdfs:label "Residential Mortgage Pool"@en .

fis:CommercialMortgagePool a owl:Class ;
    rdfs:subClassOf fis:MortgagePool ;
    rdfs:label "Commercial Mortgage Pool"@en .

fis:Exchange a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Exchange"@en ;
    rdfs:comment "An organized and officially recognized marketplace for trading financial instruments."@en .

fis:StockExchange a owl:Class ;
    rdfs:subClassOf fis:Exchange ;
    rdfs:label "Stock Exchange"@en .

fis:DerivativesExchange a owl:Class ;
    rdfs:subClassOf fis:Exchange ;
    rdfs:label "Derivatives Exchange"@en, "Futures and Options Exchange"@en .

fis:LegalEntity a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Legal Entity"@en .

fis:Issuer a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Issuer"@en ;
    rdfs:comment "The company or other entity that issues a security or incurs debt under an instrument."@en .

fis:Corporation a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Corporation"@en, "Company"@en .

fis:FinancialInstitution a owl:Class ;
    rdfs:subClassOf fis:Corporation ;
    rdfs:label "Financial Institution"@en .

fis:Bank a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Bank"@en, "Credit Institution"@en .

fis:CentralBank a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Central Bank"@en .

fis:Government a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Government"@en .

fis:SovereignGovernment a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Sovereign Government"@en, "National Government"@en .

fis:LocalGovernment a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Local Government"@en, "Municipality"@en, "Sub-Sovereign Government"@en .

fis:SupranationalOrganization a owl:Class ;
    rdfs:subClassOf fis:Issuer ;
    rdfs:label "Supranational Organization"@en .

fis:Investor a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Investor"@en .

fis:RetailInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Retail Investor"@en .

fis:InstitutionalInvestor a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Institutional Investor"@en .

fis:Shareholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Shareholder"@en, "Stockholder"@en .

fis:Bondholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:label "Bondholder"@en .

#################################################################
#    Classes: Financial Instruments
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:comment "A monetary contract between parties that gives rise to a financial asset of one entity and a financial liability or equity instrument of another."@en .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Cash Instrument"@en ;
    rdfs:comment "A financial instrument whose value is determined directly by the markets, comprising transferable securities and non-securities such as loans and deposits."@en .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Loan"@en .

fis:Deposit a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Deposit"@en .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Security"@en ;
    rdfs:comment "A tradable financial asset representing a claim on an issuer. Note: Jurisdictions conflict on whether derivatives are included under the legal definition of 'security' (broad in the US and ECB capital markets context; narrow in the UK FCA Handbook which restricts securities to debt and equity). Here modeled under CashInstrument in accordance with majority financial market classification, with derivatives forming a distinct branch."@en .

fis:BearerSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Bearer Security"@en .

fis:RegisteredSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Registered Security"@en .

#################################################################
#    Classes: Debt Securities
#################################################################

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security"@en, "Fixed Income Security"@en ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise on the part of the issuer to make payments of principal and/or interest to the holder."@en .

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument"@en, "Money Market Paper"@en ;
    rdfs:comment "A short-term debt security with an original maturity of one year or less."@en .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper"@en, "CP"@en .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit"@en, "CD"@en .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Treasury Bill"@en, "T-Bill"@en .

fis:Banknote a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Banknote"@en .

fis:Debenture a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Debenture"@en .

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond"@en ;
    rdfs:comment "A debt security, typically longer-term (with maturity of at least one year), under which the issuer contracts to pay the holder a fixed principal amount and periodic coupons."@en .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:label "Corporate Bond"@en .

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:label "Government Bond"@en, "Sovereign Bond"@en, "Treasury Bond"@en .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
        )
    ] ;
    rdfs:label "Municipal Bond"@en, "Sub-Sovereign Government Bond"@en, "Local Authority Bond"@en .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] ;
    rdfs:label "Supranational Bond"@en, "Supra"@en .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:AssetPool ]
        )
    ] ;
    rdfs:label "Asset-Backed Security"@en, "ABS"@en .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:AssetBackedSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:MortgagePool ]
        )
    ] ;
    rdfs:label "Mortgage-Backed Security"@en, "MBS"@en .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:MortgageBackedSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgagePool ]
        )
    ] ;
    rdfs:label "Residential Mortgage-Backed Security"@en, "RMBS"@en .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:MortgageBackedSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgagePool ]
        )
    ] ;
    rdfs:label "Commercial Mortgage-Backed Security"@en, "CMBS"@en .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation"@en, "CDO"@en .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation"@en, "CMO"@en .

fis:CoveredBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond"@en ;
    rdfs:comment "A debt security backed by cash flows from mortgages or public sector assets that remain on the issuer balance sheet."@en .

fis:FixedRateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond"@en .

fis:FloatingRateNote a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note"@en, "FRN"@en, "Floater"@en .

fis:ZeroCouponBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Zero-Coupon Bond"@en, "Discount Bond"@en, "Deep Discount Bond"@en .

fis:InflationIndexedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond"@en, "Index-Linked Bond"@en, "Linker"@en .

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Callable Bond"@en .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Putable Bond"@en, "Retractable Bond"@en .

fis:PerpetualBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond"@en, "Perpetuity"@en .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Exchangeable Bond"@en .

#################################################################
#    Classes: Equity & Hybrid Securities
#################################################################

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security"@en, "Stock"@en, "Share"@en, "Capital Stock"@en ;
    rdfs:comment "A negotiable financial instrument representing ownership of an equity stake or residual claim in an entity."@en .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Common Stock"@en, "Ordinary Share"@en, "Voting Share"@en ;
    rdfs:comment "A class of equity ownership that entitles the holder to residual profit distributions and voting rights."@en .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity , fis:HybridSecurity ;
    rdfs:label "Preferred Stock"@en, "Preference Share"@en, "Preferred Share"@en ;
    rdfs:comment "A class of equity ownership that ranks senior to common stock in dividend payments and liquidation proceeds."@en .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:comment "A security combining characteristics of both debt and equity instruments."@en .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasCommonStock ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Bond"@en, "Convertible Note"@en, "Convertible Debenture"@en ;
    rdfs:comment "A bond that gives the holder the right to convert the debt into common stock of the issuing company. Note: Market convention views it as a single debt security, while accounting standard IAS 32 splits it into liability and equity components."@en .

#################################################################
#    Classes: Investment Funds & Depositary Receipts
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Investment Fund"@en, "Collective Investment Scheme"@en ;
    rdfs:comment "A pooled investment vehicle whose value is derived from a diversified portfolio of securities or other assets."@en .

fis:MutualFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund"@en, "Open-End Investment Company"@en .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:InvestmentFund
            [ a owl:Restriction ; owl:onProperty fis:hasExchange ; owl:someValuesFrom fis:StockExchange ]
        )
    ] ;
    rdfs:label "Exchange-Traded Fund"@en, "ETF"@en .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Hedge Fund"@en .

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Depositary Receipt"@en, "DR"@en ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities."@en .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American Depositary Receipt"@en, "ADR"@en .

fis:EuropeanDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European Depositary Receipt"@en, "EDR"@en .

fis:GlobalDepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "Global Depositary Receipt"@en, "GDR"@en .

#################################################################
#    Classes: Derivatives
#################################################################

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Underlying ]
        )
    ] ;
    rdfs:label "Derivative"@en, "Derivative Contract"@en, "Derivative Instrument"@en ;
    rdfs:comment "A financial contract whose value is derived from the value and characteristics of one or more underlying reference entities."@en .

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Forward"@en, "Forward Contract"@en ;
    rdfs:comment "A customized, non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today."@en .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Future"@en, "Futures Contract"@en ;
    rdfs:comment "A standardized contract traded on an exchange to buy or sell a specified asset at a predetermined price on a specified future date. Note: The BIS taxonomy classifies futures as standardized exchange-traded forwards, while CFI and general market taxonomy treat futures and forwards as four distinct derivatives."@en .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option"@en, "Option Contract"@en ;
    rdfs:comment "A contract conveying the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date."@en .

fis:CallOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option"@en .

fis:PutOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option"@en .

fis:AmericanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option"@en .

fis:EuropeanOption a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option"@en .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Warrant"@en, "Equity Warrant"@en .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap"@en, "Swap Agreement"@en ;
    rdfs:comment "A contract in which two counterparties agree to exchange cash flow streams according to a prearranged formula."@en .

fis:InterestRateSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap"@en .

fis:CurrencySwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap"@en .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Swap
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ]
        )
    ] ;
    rdfs:label "Credit Default Swap"@en, "CDS"@en .

fis:EquityDerivative a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
        )
    ] ;
    rdfs:label "Equity Derivative"@en, "Stock Derivative"@en .

fis:StockOption a owl:Class ;
    rdfs:subClassOf fis:Option , fis:EquityDerivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Option
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
        )
    ] ;
    rdfs:label "Stock Option"@en .

fis:StockFuture a owl:Class ;
    rdfs:subClassOf fis:Future , fis:EquityDerivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Future
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
        )
    ] ;
    rdfs:label "Stock Future"@en .

#################################################################
#    Disjointness Axioms
#################################################################

fis:CashInstrument owl:disjointWith fis:Derivative .

fis:DebtSecurity owl:disjointWith fis:EquitySecurity .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption owl:disjointWith fis:EuropeanOption .

fis:BearerSecurity owl:disjointWith fis:RegisteredSecurity .

fis:RetailInvestor owl:disjointWith fis:InstitutionalInvestor .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

fis:CoveredBond owl:disjointWith fis:AssetBackedSecurity .

[ a owl:AllDisjointClasses ;
  owl:members (
    fis:Security
    fis:Loan
    fis:Deposit
  )
] .

[ a owl:AllDisjointClasses ;
  owl:members (
    fis:Forward
    fis:Future
    fis:Option
    fis:Swap
  )
] .

[ a owl:AllDisjointClasses ;
  owl:members (
    fis:Corporation
